SELECT *
FROM t_code
WHERE parent_code = #{ parentCode }
AND proj_sq = #{ projSq }

	and access = 'Y'

ORDER BY odr;

SELECT count(*)
FROM t_code
WHERE parent_code = #{ parentCode }
	AND proj_sq = #{ projSq }
	and access = 'Y'

SELECT c.*
FROM t_code c
	     JOIN designkit.t_project p ON c.proj_sq = p.sq
WHERE c.code = #{code}
	AND p.slug = #{slug}

mapper.insert:
INSERT INTO t_code (proj_sq, code, parent_code, label, data, access, odr)
SELECT #{ projSq }, #{ code }, #{ parentCode }, #{ label }, #{ data }, #{ access }, count(*) + 1
FROM t_code
WHERE proj_sq = #{ projSq }


		AND parent_code = #{ parentCode }


		AND parent_code IS NULL

mapper.update:
UPDATE t_code
SET label   = #{ label },
    data    = #{ data },
    access  = #{ access },
    article = #{ article }
WHERE code = #{ code }
	AND proj_sq = #{ projSq }

mapper.delete:
DELETE FROM t_code
WHERE proj_sq = #{projSq}
	AND code IN (
	WITH RECURSIVE cte AS (
		SELECT code FROM t_code
		WHERE code = #{code} AND proj_sq = #{projSq}
		UNION ALL
		SELECT c.code FROM t_code c
			                   INNER JOIN cte ON c.parent_code = cte.code
		WHERE c.proj_sq = #{projSq}
	)
	SELECT code FROM cte
)

mapper.select:
SELECT count(*)
from t_code
WHERE code = #{ code }
	AND proj_sq = #{ projSq }

mapper.update:
UPDATE t_code
SET odr = #{ odr }
WHERE code = #{ code }
	AND proj_sq = #{ projSq }
